//! The generated files: one crate per segment (a library to deploy it from
//! any program, and a binary that deploys it on its own), and the crossing
//! report.
//!
//! A segment crate depends on gdl, the contract, and the implementation
//! crates of the nodes it hosts, and on nothing else of the graph's: an
//! implementation's native dependencies stay out of every other segment's
//! build.

use std::collections::BTreeMap;
use std::fmt::Write;
use std::path::{Path, PathBuf};

use gdl_model::{Layout, Manifest, Role};

mod binary;

use crate::Error;
use crate::laid::Laid;
use crate::paths::{display, relative};
use crate::spec::{Contract, CrateSource, Spec};

/// Marks every generated file. `--check` and stale-file cleanup find
/// generated files by it.
pub(crate) const MARKER: &str = "@generated by gdl-gen; do not edit";

/// How generated manifests name the crates they depend on.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Deps {
    /// By paths relative to each manifest: crates generated beside the
    /// crates they depend on, and committed with them.
    Relative,
    /// Every crate the spec names by its absolute path, and each manifest
    /// its own workspace root: a tarball expanded anywhere on the machine
    /// that made it, even inside another workspace. Only the generated
    /// contract is inside the archive, and the segment manifests name it
    /// by its place there; where a listed crate sits on disk decides
    /// nothing.
    Exported,
}

impl Deps {
    /// How a manifest in `from` names the listed crate in `target` (both
    /// absolute), as a TOML string.
    pub(crate) fn path(self, from: &Path, target: &Path) -> String {
        let target = crate::dump::absolute(target).unwrap_or_else(|_| target.to_path_buf());
        let path = match self {
            Self::Exported => target,
            Self::Relative => relative(from, &target),
        };
        crate::dump::toml_string(&display(&path))
    }

    /// What ends a manifest: an empty `[workspace]` for an exported one.
    pub(crate) fn workspace(self) -> &'static str {
        match self {
            Self::Relative => "",
            Self::Exported => {
                "\n# Its own workspace, wherever the tarball is expanded.\n[workspace]\n"
            }
        }
    }
}

/// Everything to write under the output directory for layout `laid`,
/// keyed by path relative to it: under the layout's own directory when the
/// spec has several. `out` is the output directory, absolute and
/// normalized.
pub(crate) fn files(
    spec: &Spec,
    laid: &Laid<'_>,
    contract: &Contract,
    manifest: &Manifest,
    layout: &Layout,
    out: &Path,
    deps: Deps,
) -> Result<BTreeMap<PathBuf, String>, Error> {
    let placement = laid.placement;
    let segments: Vec<&str> = placement.segments().map(|(name, _)| name).collect();
    let spec_dir = crate::dump::absolute(&spec.dir)?;
    let dir = laid.dir();
    let mut files = BTreeMap::new();
    for (segment, nodes) in placement.segments() {
        let crate_dir = out.join(&dir).join(segment);
        let regenerate = regenerate_command(spec, &spec_dir, &crate_dir, out, deps);
        let unit = Unit {
            spec,
            placement,
            package: laid.package(&manifest.name, segment),
            contract,
            manifest,
            segment,
            segments: &segments,
            nodes,
            crate_dir: &crate_dir,
            out,
            deps,
            regenerate: &regenerate,
        };
        let path = dir.join(segment);
        files.insert(path.join("Cargo.toml"), unit.cargo_toml());
        files.insert(path.join("src/lib.rs"), rustfmt(&unit.lib_rs())?);
        files.insert(path.join("src/main.rs"), rustfmt(&unit.main_rs())?);
    }
    files.insert(
        dir.join("crossings.txt"),
        format!(
            "# {MARKER}\n# Crossings for one request through each root of `{}` under this placement.\n{}\n",
            manifest.name,
            layout.report()
        ),
    );
    Ok(files)
}

/// Format generated Rust as `cargo fmt` would, so formatting the generated
/// crates is not drift. The text is built line by line; rustfmt owns the
/// layout, rather than a second copy of its rules here.
fn rustfmt(text: &str) -> Result<String, Error> {
    use std::io::Write as _;
    use std::process::{Command, Stdio};

    // rustfmt reads a `rustfmt.toml` from where it runs and above. Run it
    // with a config of its own, so the output does not depend on where the
    // generator is run.
    let (_dir, config) = rustfmt_config()?;
    let rustfmt = std::env::var_os("RUSTFMT").unwrap_or_else(|| "rustfmt".into());
    let mut child = Command::new(rustfmt)
        .args([
            "--edition",
            "2024",
            "--emit",
            "stdout",
            "--quiet",
            "--config-path",
        ])
        .arg(&config)
        .current_dir(config.parent().unwrap_or(&config))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| Error::new(format!("running rustfmt: {e}")))?;
    child
        .stdin
        .take()
        .ok_or_else(|| Error::new("rustfmt has no stdin"))?
        .write_all(text.as_bytes())
        .map_err(|e| Error::new(format!("writing to rustfmt: {e}")))?;
    let output = child
        .wait_with_output()
        .map_err(|e| Error::new(format!("running rustfmt: {e}")))?;
    if !output.status.success() {
        return Err(Error::new(format!(
            "rustfmt rejected generated code (a gdl-gen bug):\n{}\n{text}",
            String::from_utf8_lossy(&output.stderr)
        )));
    }
    String::from_utf8(output.stdout).map_err(|e| Error::new(format!("rustfmt output: {e}")))
}

/// A directory of its own holding the default rustfmt config, and the
/// config's path. The directory is removed when it is dropped: one left
/// behind per run filled the temporary directory.
fn rustfmt_config() -> Result<(tempfile::TempDir, PathBuf), Error> {
    let dir = tempfile::Builder::new()
        .prefix("gdl-gen-rustfmt-")
        .tempdir()
        .map_err(|e| Error::new(format!("a directory for rustfmt's config: {e}")))?;
    let file = dir.path().join("rustfmt.toml");
    std::fs::write(&file, "edition = \"2024\"\n")
        .map_err(|e| Error::new(format!("{}: {e}", file.display())))?;
    Ok((dir, file))
}

/// The package that graph `graph` generates for `part`: a segment, or the
/// contract.
pub(crate) fn package_name(graph: &str, part: &str) -> String {
    format!("{}-{}", slug(graph), slug(part))
}

fn slug(name: &str) -> String {
    name.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect()
}

/// The command that regenerates the output, run from the generated crate's
/// directory.
fn regenerate_command(
    spec: &Spec,
    spec_dir: &Path,
    crate_dir: &Path,
    out: &Path,
    deps: Deps,
) -> String {
    let file = spec.file.file_name().unwrap_or_default();
    if deps == Deps::Exported {
        // A spec given as text is in the archive, beside the segments.
        if spec.text.is_some() {
            return "cargo gdl export --spec ../gdl.toml --out <archive.tar.gz>".to_string();
        }
        return export_command(&spec_dir.join(file));
    }
    let spec_file = display(&relative(crate_dir, &spec_dir.join(file)));
    let out = display(&relative(crate_dir, out));
    format!(
        "cargo gdl generate --spec \"{}\" --out \"{}\"",
        spec_file.escape_debug(),
        out.escape_debug()
    )
}

/// The command that exports from the spec at `spec`, for a comment: the
/// path quoted, with any character that would end the comment escaped (a
/// path may hold a line break), and the archive left for the reader to
/// name. The regenerate command quotes its paths the same way.
fn export_command(spec: &Path) -> String {
    format!(
        "cargo gdl export --spec \"{}\" --out <archive.tar.gz>",
        display(spec).escape_debug()
    )
}

struct Unit<'a> {
    spec: &'a Spec,
    placement: &'a gdl_model::Placement,
    /// The segment's package.
    package: String,
    contract: &'a Contract,
    manifest: &'a Manifest,
    segment: &'a str,
    segments: &'a [&'a str],
    nodes: &'a [String],
    crate_dir: &'a Path,
    out: &'a Path,
    deps: Deps,
    regenerate: &'a str,
}

/// One hosted node that takes an implementation.
struct Hosted<'a> {
    name: &'a str,
    binding: &'a str,
    package: &'a str,
    ty: &'a str,
}

impl Unit<'_> {
    fn package(&self) -> String {
        self.package.clone()
    }

    fn lib(&self) -> String {
        self.package().replace('-', "_")
    }

    /// Hosted nodes that take a binding, in declaration order; validation
    /// guarantees each has one, and an implementation.
    fn hosted(&self) -> Vec<Hosted<'_>> {
        self.manifest
            .nodes
            .iter()
            .filter(|node| node.binding.is_some() && self.nodes.contains(&node.name))
            .map(|node| {
                let bind = &self.spec.bind[&node.name];
                Hosted {
                    name: &node.name,
                    binding: node.binding.as_deref().unwrap_or_default(),
                    package: &bind.package,
                    // `::crate::Type` and `crate::Type` are one path; the
                    // emitted code adds the root itself.
                    ty: bind.ty.trim().trim_start_matches("::"),
                }
            })
            .collect()
    }

    /// The source that hosts the frontend: the one the spec pins, which
    /// validation has checked is at most one.
    fn frontend_source(&self) -> Option<&gdl_model::NodeInfo> {
        self.manifest
            .nodes
            .iter()
            .find(|node| node.role == Role::Source && self.spec.bind.contains_key(&node.name))
    }

    /// The frontend's binding, when this segment hosts it.
    fn frontend(&self) -> Option<&crate::spec::Bind> {
        let source = self.frontend_source()?;
        if !self.nodes.contains(&source.name) {
            return None;
        }
        self.spec.bind.get(&source.name)
    }

    fn hosts_source(&self) -> bool {
        self.manifest
            .nodes
            .iter()
            .any(|node| node.role == Role::Source && self.nodes.contains(&node.name))
    }

    /// Whether the binary can serve the source over JSON lines: both of the
    /// source's types must be serde types, and its request one value. One
    /// line cannot carry a streamed request.
    fn serves(&self) -> bool {
        let Some(hop) = self.manifest.hops.first() else {
            return false;
        };
        let req = hop
            .forward_types
            .first()
            .is_some_and(|t| t.wire && t.stream.is_none());
        let item = hop.backward_types.last().is_some_and(|t| t.wire);
        self.manifest
            .nodes
            .iter()
            .filter(|n| n.role == Role::Source)
            .count()
            == 1
            && self.hosts_source()
            && self.frontend().is_none()
            && req
            && item
    }

    /// Whether the source takes a streamed request.
    fn streamed_source(&self) -> bool {
        self.manifest
            .hops
            .first()
            .and_then(|hop| hop.forward_types.first())
            .is_some_and(|t| t.stream.is_some())
    }

    fn path_to(&self, target: &Path) -> String {
        self.deps.path(self.crate_dir, target)
    }

    /// The contract's path: in an export, a generated contract is in the
    /// archive beside the segment.
    fn contract_path(&self) -> String {
        let generated = matches!(self.spec.source, crate::spec::Source::Graph(_));
        if self.deps == Deps::Exported && generated {
            let path = relative(self.crate_dir, &self.out.join("contract"));
            crate::dump::toml_string(&display(&path))
        } else {
            self.path_to(&self.contract.path)
        }
    }

    fn cargo_toml(&self) -> String {
        let package = self.package();
        let mut text = String::new();
        let _ = writeln!(text, "# {MARKER}.");
        let _ = writeln!(text, "# Regenerate with: {}", self.regenerate);
        let _ = writeln!(text);
        let _ = writeln!(text, "[package]");
        let _ = writeln!(text, "name = \"{package}\"");
        let _ = writeln!(text, "version = \"0.0.0\"");
        let _ = writeln!(text, "edition = \"2024\"");
        let _ = writeln!(text, "publish = false");
        let _ = writeln!(text);
        let _ = writeln!(text, "[lib]");
        let _ = writeln!(text, "path = \"src/lib.rs\"");
        let _ = writeln!(text);
        let _ = writeln!(text, "[[bin]]");
        let _ = writeln!(text, "name = \"{package}\"");
        let _ = writeln!(text, "path = \"src/main.rs\"");
        let _ = writeln!(text);
        let _ = writeln!(text, "[dependencies]");
        let source = self.spec.gdl.source(&|path| self.path_to(path));
        // Hub discovery brings the hub client and its HTTP stack; only a
        // spec that deploys asks for it.
        let features: Vec<&str> = [
            ("json-lines", self.serves()),
            ("hub", self.spec.deployment.is_some()),
        ]
        .into_iter()
        .filter_map(|(feature, wanted)| wanted.then_some(feature))
        .collect();
        let gdl = if features.is_empty() {
            format!("{{ {source} }}")
        } else {
            format!("{{ {source}, features = {features:?} }}")
        };
        let _ = writeln!(text, "gdl-runtime = {gdl}");
        let _ = writeln!(
            text,
            "{} = {{ path = {} }}",
            self.contract.package,
            self.contract_path()
        );
        // Each implementation crate once, however many nodes it implements.
        let mut implementations: BTreeMap<&str, &CrateSource> = BTreeMap::new();
        for node in self.hosted() {
            implementations.insert(node.package, &self.spec.bind[node.name].source);
        }
        if let Some(frontend) = self.frontend() {
            implementations.insert(&frontend.package, &frontend.source);
        }
        if self.hosts_source()
            && let Some(service) = &self.spec.service
        {
            for node in service.nodes() {
                implementations.insert(&node.bind.package, &node.bind.source);
            }
        }
        for (package, source) in implementations {
            let source = source.source(&|path| self.path_to(path));
            let _ = writeln!(text, "{package} = {{ {source} }}");
        }
        let _ = writeln!(
            text,
            "serde = {{ version = \"1\", features = [\"derive\"] }}"
        );
        let _ = writeln!(
            text,
            "tokio = {{ version = \"1\", features = [\"io-std\", \"io-util\", \"macros\"] }}"
        );
        let _ = writeln!(text, "toml = \"0.9\"");
        text.push_str(self.deps.workspace());
        text
    }

    fn lib_rs(&self) -> String {
        let hosted = self.hosted();
        let mut text = String::new();
        let _ = writeln!(text, "// {MARKER}.");
        let _ = writeln!(text, "// Regenerate with: {}", self.regenerate);
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "//! Segment `{}` of graph `{}`, hosting {}.",
            self.segment,
            self.manifest.name,
            list(self.nodes)
        );
        let _ = writeln!(text, "//!");
        let _ = writeln!(
            text,
            "//! [`start`] deploys it inside a program; the `{}` binary deploys it on",
            self.package()
        );
        let _ = writeln!(text, "//! its own, through [`Binary`].");
        let _ = writeln!(text);
        // Paths from the crate root (`::`), here and for every
        // implementation: a hosted crate called `contract` must not be
        // shadowed by this alias.
        let _ = writeln!(
            text,
            "pub use ::{} as contract;",
            self.contract.module.trim().trim_start_matches("::")
        );
        let _ = writeln!(text);
        let _ = writeln!(text, "/// This segment's name in the placement.");
        let _ = writeln!(text, "pub const SEGMENT: &str = \"{}\";", self.segment);
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "/// Every segment of the placement: an instance waits for all of them."
        );
        let quoted: Vec<String> = self.segments.iter().map(|s| format!("\"{s}\"")).collect();
        let _ = writeln!(
            text,
            "pub const SEGMENTS: &[&str] = &[{}];",
            quoted.join(", ")
        );
        let _ = writeln!(text);
        let _ = writeln!(text, "/// The placement this crate was generated for.");
        let placement = toml::to_string(self.placement).unwrap_or_default();
        let _ = writeln!(
            text,
            "pub const PLACEMENT: &str = {};",
            raw_string(&placement)
        );
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "/// The implementations of the nodes this segment hosts."
        );
        if hosted.is_empty() {
            let _ = writeln!(text, "pub struct Nodes {{}}");
        } else {
            let _ = writeln!(text, "pub struct Nodes {{");
            for node in &hosted {
                let _ = writeln!(text, "    /// Node `{}`.", node.name);
                let _ = writeln!(text, "    pub {}: ::{},", node.binding, node.ty);
            }
            let _ = writeln!(text, "}}");
        }
        let _ = writeln!(text);
        let _ = writeln!(
            text,
            "/// Deploy this segment on `node`. Every segment's instances must be in"
        );
        let _ = writeln!(text, "/// `roster`.");
        let _ = writeln!(text, "pub fn start(");
        let _ = writeln!(text, "    node: gdl_runtime::velo::Velo,");
        let _ = writeln!(text, "    roster: &gdl_runtime::Roster,");
        let _ = writeln!(text, "    config: gdl_runtime::RuntimeConfig,");
        let _ = writeln!(text, "    nodes: Nodes,");
        let _ = writeln!(text, ") -> gdl_runtime::gdl::Result<");
        let roots: Vec<_> = self
            .manifest
            .hops
            .iter()
            .filter(|h| {
                self.manifest
                    .node(&h.outer)
                    .is_some_and(|n| n.role == Role::Source)
            })
            .collect();
        let root_type = |root: &gdl_model::HopInfo| {
            format!(
                "impl gdl_runtime::gdl::Next<<contract::nodes::{} as gdl_runtime::SourceDecl>::Req, <contract::nodes::{} as gdl_runtime::SourceDecl>::Item> + gdl_runtime::Register + use<>",
                root.outer, root.outer
            )
        };
        let root = if roots.len() == 1 {
            root_type(roots[0])
        } else {
            roots.iter().rev().fold("()".into(), |tail, root| {
                format!("({}, {tail})", root_type(root))
            })
        };
        let _ = writeln!(text, "    gdl_runtime::Segment<{root}>,");
        let _ = writeln!(text, "> {{");
        let _ = writeln!(
            text,
            "    let placement = gdl_runtime::Placement::from_toml(PLACEMENT)?;"
        );
        let _ = writeln!(text, "    let manifest = contract::manifest();");
        let _ = writeln!(
            text,
            "    let deployment = gdl_runtime::Deployment::new(node, &manifest, &placement, SEGMENT, roster, config)?;"
        );
        let mut bindings = String::from("contract::Bindings::new()");
        for node in &hosted {
            let _ = write!(bindings, ".{0}(nodes.{0})", node.binding);
        }
        if hosted.is_empty() {
            let _ = writeln!(text, "    let Nodes {{}} = nodes;");
        }
        let _ = writeln!(
            text,
            "    let root = contract::assemble(&deployment, {bindings})?;"
        );
        let _ = writeln!(text, "    deployment.start(root)");
        let _ = writeln!(text, "}}");
        let _ = writeln!(text);
        text.push_str(&self.binary_rs());
        text
    }
}

fn list(nodes: &[String]) -> String {
    let quoted: Vec<String> = nodes.iter().map(|n| format!("`{n}`")).collect();
    quoted.join(", ")
}

/// A Rust raw string literal holding `text`, with enough `#`s.
fn raw_string(text: &str) -> String {
    let mut hashes = 1;
    while text.contains(&format!("\"{}", "#".repeat(hashes))) {
        hashes += 1;
    }
    let h = "#".repeat(hashes);
    format!("r{h}\"{text}\"{h}")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// In an export, every crate the spec names is outside the archive,
    /// wherever it sits on disk, even under the output's directory: only
    /// the generated contract is inside, and its manifest line says so.
    #[test]
    fn an_export_names_every_listed_crate_by_its_absolute_path() {
        let out = Path::new("/work/.gdl-export");
        let from = out.join("front");
        assert_eq!(
            Deps::Exported.path(&from, &out.join("nodes")),
            "\"/work/.gdl-export/nodes\""
        );
        assert_eq!(
            Deps::Relative.path(&from, &out.join("nodes")),
            "\"../nodes\""
        );
    }

    /// A spec's path may hold any character; the comment that names it
    /// stays one line.
    #[test]
    fn the_export_command_stays_on_its_line() {
        assert_eq!(
            export_command(Path::new("/work/line\nbreak/gdl.toml")),
            "cargo gdl export --spec \"/work/line\\nbreak/gdl.toml\" --out <archive.tar.gz>"
        );
    }
}
